def error_report(log_text: str) -> list:
    """Summarizes a server log.

    Each valid line looks like:
    2026-08-11T14:23:05Z LEVEL message text here

    where LEVEL is INFO, WARN, or ERROR (case-sensitive).
    Return a list of strings "HH: N errors" (HH = two-digit UTC hour,
    N = count of ERROR lines in that hour), sorted by hour ascending,
    including only hours that have at least one ERROR. Ignore malformed
    lines entirely. Return [] if there are no errors.
    """
    hourly_errors = {}
    for line in log_text.splitlines():
        if not line:
            continue
        try:
            parts = line.split()
            if len(parts) < 2:
                continue
            level = parts[1].strip().upper()
            if level == "ERROR":
                time_str = parts[0]
                if len(time_str) >= 19 and time_str[-6:] == 'Z':
                    try:
                        hour = int(time_str[:2])
                        if hour not in hourly_errors:
                            hourly_errors[hour] = 0
                        hourly_errors[hour] += 1
                    except ValueError:
                        pass  # Ignore invalid time format
        except Exception:
            pass

    result = []
    for hour, count in hourly_errors.items():
        if count > 0:
            result.append(f"{hour:02d}: {count} errors")

    result.sort()
    return result


